def test_project_memory_leetcode_record_maps_to_memory_source() -> None:
    sources = _memory_items_to_sources(
        {
            "found": True,
            "should_scan": False,
            "confidence": 65.12,
            "items": [
                {
                    "_key": "live-evidence-eval-minimum-remove-valid-parentheses",
                    "title": "LeetCode: Minimum Remove to Make Valid Parentheses",
                    "topic_id": "leetcode/minimum-remove-to-make-valid-parentheses",
                    "topic_kind": "leetcode_problem",
                    "project_id": "live-evidence",
                    "source_locator": "project_memory_versions/live-evidence-eval-minimum-remove-valid-parentheses",
                    "retrieval_text": (
                        "Use a stack of opening-parenthesis indices and invalid closing indices, "
                        "then rebuild the string."
                    ),
                    "tags": ["live-evidence", "leetcode-problem-index", "stack"],
                    "_source": "project_memory_active",
                    "scores": {"bm25": 65.12, "dense": 0.81, "graph": 0.0},
                }
            ],
        },
        "procedural_memory",
        profile(),
    )

    assert len(sources) == 1
    assert sources[0].label == "LeetCode: Minimum Remove to Make Valid Parentheses"
    assert "rebuild the string" in sources[0].excerpt
    assert sources[0].repository == "live-evidence"
    assert sources[0].path == "project_memory_versions/live-evidence-eval-minimum-remove-valid-parentheses"
    assert sources[0].metadata["_key"] == "live-evidence-eval-minimum-remove-valid-parentheses"
    assert sources[0].metadata["source"] == "project_memory_active"
    assert sources[0].score > 0.8


